"""Prediction-error condition for learned recovery.

Input is the fixed-length feature vector produced by
``runtime.prediction_error.PredictionErrorFeatures.vector()``: the earlier
forecast, the executed command prefix and the aligned real outcome, each with
its validity bits. The encoder turns it into a few und-space tokens that the
existing action branch reads through cross-attention; actions are still
generated by the action branch (no direct error-to-action correction).

The capability needs recovery data: an untrained encoder only adds an
uninformative condition. ``world_model._prepend_recovery`` omits the tokens for
samples without a valid condition instead of feeding zeros.
"""
from __future__ import annotations

import torch
import torch.nn as nn


class RecoveryEncoder(nn.Module):
    def __init__(self, feature_dim: int, dim: int, num_tokens: int = 4, hidden: int = 512):
        super().__init__()
        self.feature_dim, self.dim, self.num_tokens = feature_dim, dim, num_tokens
        self.net = nn.Sequential(
            nn.LayerNorm(feature_dim),
            nn.Linear(feature_dim, hidden), nn.SiLU(),
            nn.Linear(hidden, num_tokens * dim),
        )
        self.slot_embed = nn.Parameter(torch.zeros(1, num_tokens, dim).normal_(std=0.02))
        nn.init.normal_(self.net[-1].weight, std=0.02)
        nn.init.zeros_(self.net[-1].bias)

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        if features.dim() != 2 or features.size(1) != self.feature_dim:
            raise ValueError(f"recovery features must be [B, {self.feature_dim}]")
        x = self.net(features.to(self.net[1].weight.dtype).nan_to_num(0.0))
        return x.view(features.size(0), self.num_tokens, self.dim) + self.slot_embed
